export function resolveLang(lang) {
  if (!lang) return 'en';
  if (lang === 'auto') return 'auto';
  if (lang.startsWith('zh')) return lang.includes('Hant') || lang.includes('TW') || lang.includes('HK') ? 'zh-Hant' : 'zh-Hans';
  if (lang.startsWith('pt')) return 'pt';
  if (lang.startsWith('nb') || lang.startsWith('no') || lang.startsWith('nn')) return 'nb';
  if (SUPPORTED_LANGS.has(lang)) return lang;
  const base = lang.split('-')[0];
  if (SUPPORTED_LANGS.has(base)) return base;
  return 'en';
}

export function getLabels(configLang, hassLang) {
  const code = configLang === 'auto' ? resolveLang(hassLang || 'en') : resolveLang(configLang);
  return CARD_LABELS[code] || CARD_LABELS.en;
}

export function getPrecipLabel(configLang, hassLang) {
  const code = configLang === 'auto' ? resolveLang(hassLang || 'en') : resolveLang(configLang);
  return PRECIP_LABELS[code] || PRECIP_LABELS.en;
}

